{
  "version": "schemaxis.readiness/1",
  "routes": {
    "schemaxis.cantera/1": {
      "guide": "docs/cantera.md",
      "context": {
        "purpose": "Compute frozen-composition ideal-gas properties, TP/HP equilibrium sweeps or closed optionally bath-coupled constant-pressure/constant-volume reactor time histories for the ten-species hydrogen/oxygen h2o2 mechanism; export independently checked numeric state tables.",
        "assumptions": "Isolated Cantera 3.2.x Python with the qualified h2o2.yaml SHA256. Only ideal-gas ohmech phase and its 29 reactions. SI K, Pa, kg, J, s; composition amounts are explicitly mole or mass basis and normalised. Reactors are closed and homogeneous (adiabatic by default, or constant total thermal conductance to a fixed-temperature bath) with Cantera's default 1 m3 initial volume.",
        "constraints": "Two nodes. Sweeps: 2\u2013100 independent temperature samples, 300\u20133500 K initial and final temperatures, 1000\u201310000000 Pa. Reactor histories: one initial temperature 300\u20133500 K, 2\u2013100 strictly increasing sample times, each in seconds between 0 and 1, rtol 1e-12\u20131e-8, atol 1e-20\u20131e-12, maxSteps 100\u2013100000 and all states within 300\u20133500 K. H2,H,O,O2,OH,H2O,HO2,H2O2,AR,N2 only. N2/Ar are inert; no NOx, carbon, condensed phases, transport, moving/radiating walls, wall/bath heat capacity, inflow or flames. Thermal conductance 0\u20131000000 W/K and fixed bath 300\u20133500 K; zero conductance is adiabatic. Bath heating can cross the temperature-rise criterion without chemistry.",
        "inspection": "Read results.csv with numeric columns including units and X_/Y_ species fractions; reactor tables start with time_s instead of initialTemperature_K. chemistry-summary.json explains mechanism hash, phase, input basis, independent element/equilibrium/energy residuals and, for reactors, model, read-back solver settings, the declared ignition criterion and delay, and verification tolerances. Keep both when handing the table to Calc. Thermal summaries distinguish independently integrated heat input J/kg and native instantaneous outward heat rate W, with independently checked energy changes.",
        "recovery": "INVALID_COMPOSITION needs distinct supported species and positive total amount. INVALID_TIMES needs strictly increasing reactor sample times. INTERPRETER_NOT_FOUND needs an absolute executable Python; NATIVE_UNAVAILABLE means it cannot import Cantera; UNSUPPORTED_RUNTIME means Cantera is not 3.2.x (see observed.version). UNSUPPORTED_STATE means a reactor state left 300\u20133500 K; dilute the mixture or start colder. A changed mechanism needs explicit requalification. HP states outside 300\u20133500 K fail verification; choose a supported initial state/composition. Native failures retain logs; use a fresh directory after correcting input. If strong heat loss produces a negative trace fraction near solver absolute tolerance, tighten absoluteTolerance (for example 1e-18); fractions remain strictly nonnegative at verification. Keep all temperature bounds and verification tolerances."
      },
      "examples": [
        {
          "id": "baseline",
          "reference": "examples/schemaxis/cantera-minimal.json"
        },
        {
          "id": "equilibrium",
          "reference": "examples/schemaxis/cantera-equilibrium.json"
        },
        {
          "id": "adiabatic",
          "reference": "examples/schemaxis/cantera-adiabatic.json"
        },
        {
          "id": "reactor",
          "reference": "examples/schemaxis/cantera-reactor.json"
        },
        {
          "id": "zero-composition",
          "document": {
            "version": "schemaxis.cantera/1",
            "nodes": [
              {
                "id": "gas",
                "filter": "gas",
                "options": {
                  "pressure": 101325,
                  "basis": "mole",
                  "composition": [
                    {
                      "species": "AR",
                      "amount": 0
                    }
                  ]
                }
              },
              {
                "id": "table",
                "filter": "thermoSweep",
                "inputs": {
                  "input": "gas"
                },
                "options": {
                  "temperatures": [
                    300,
                    600,
                    900
                  ]
                }
              }
            ],
            "output": "table"
          },
          "expect": "invalid",
          "fault": "INVALID_COMPOSITION",
          "schemaValid": true
        },
        {
          "id": "unordered-reactor-times",
          "document": {
            "version": "schemaxis.cantera/1",
            "nodes": [
              {
                "id": "fuelAir",
                "filter": "gas",
                "options": {
                  "pressure": 101325,
                  "basis": "mole",
                  "composition": [
                    {
                      "species": "H2",
                      "amount": 2
                    },
                    {
                      "species": "O2",
                      "amount": 1
                    },
                    {
                      "species": "N2",
                      "amount": 3.76
                    }
                  ]
                }
              },
              {
                "id": "ignition",
                "filter": "reactorHistory",
                "inputs": {
                  "input": "fuelAir"
                },
                "options": {
                  "model": "constantPressure",
                  "temperature": 1000,
                  "times": [
                    0,
                    0.0002,
                    0.0001,
                    0.001
                  ],
                  "relativeTolerance": 1e-09,
                  "absoluteTolerance": 1e-15,
                  "maxSteps": 20000,
                  "ignitionTemperatureRise": 400
                }
              }
            ],
            "output": "ignition"
          },
          "expect": "invalid",
          "fault": "INVALID_TIMES",
          "schemaValid": true
        },
        {
          "id": "thermal",
          "reference": "examples/schemaxis/cantera-thermal-reactor.json"
        },
        {
          "id": "negative-thermal-conductance",
          "document": {
            "version": "schemaxis.cantera/1",
            "nodes": [
              {
                "id": "fuelAir",
                "filter": "gas",
                "options": {
