                  "basis": "mole",
                  "composition": [
                    {
                      "species": "H2",
                      "amount": 2
                    },
                    {
                      "species": "O2",
                      "amount": 1
                    },
                    {
                      "species": "N2",
                      "amount": 3.76
                    }
                  ]
                }
              },
              {
                "id": "ignition",
                "filter": "reactorHistory",
                "inputs": {
                  "input": "fuelAir"
                },
                "options": {
                  "model": "constantPressure",
                  "temperature": 1000,
                  "times": [
                    0,
                    0.0001,
                    0.0002,
                    0.0003,
                    0.0004,
                    0.001,
                    0.005,
                    0.02
                  ],
                  "relativeTolerance": 1e-09,
                  "absoluteTolerance": 1e-15,
                  "maxSteps": 20000,
                  "ignitionTemperatureRise": 400,
                  "thermalConductance": -1,
                  "bathTemperature": 500
                }
              }
            ],
            "output": "ignition"
          },
          "expect": "invalid",
          "fault": "INVALID_ARGUMENT",
          "schemaValid": false
        }
      ],
      "conformance": [
        "tests/unit/test_cantera_admission.py",
        "tests/unit/test_cantera_reactor.py",
        "tests/unit/test_cantera_thermal.py"
      ],
      "acceptance": [
        "tools/qualify_cantera.py",
        "tools/qualify_cantera_thermal.py"
      ],
      "profiles": {
        "workflow": {
          "scope": "Verified numeric results.csv into Calc readCSV; preserve chemistry-summary.json for units, species and mechanism limits. Unchanged Cantera and workbook attempts can be reused.",
          "references": [
            "docs/cantera.md",
            "tools/qualify_cantera.py"
          ]
        },
        "composition": {
          "scope": "Shared document references, pure value functions and expressions resolve for every finite analytic visit before native validation.",
          "references": [
            "docs/adaptor-runtime.md",
            "tests/unit/test_adaptor_runtime.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://cantera.org/stable/python/thermo.html",
          "https://cantera.org/stable/reference/thermo/species-thermo.html",
          "https://raw.githubusercontent.com/Cantera/cantera/v3.2.0/data/h2o2.yaml",
          "https://cantera.org/stable/python/zerodim.html",
          "https://cantera.org/stable/reference/reactors/ideal-gas-constant-pressure-reactor.html",
          "https://cantera.org/stable/reference/reactors/ideal-gas-reactor.html",
          "https://cantera.org/stable/reference/kinetics/rate-constants.html",
          "https://cantera.org/stable/python/zerodim.html#cantera.Wall",
          "https://cantera.org/stable/python/zerodim.html#cantera.Reservoir",
          "https://cantera.org/stable/reference/reactors/interactions.html#walls"
        ],
        "lifecycle": {
          "timeout": "One total deadline bounds build (including the reactor sample and ignition passes) and fresh-process CSV reopen. ReactorNet maxSteps bounds each sample interval, the ignition pass stops after 200000 steps and host independent integration after 50000 steps. Kit watchdog independently bounds the entire attempt.",
          "cancellation": "Shared owned native process cancellation; final cancellation check precedes publication.",
          "logs": "authored.json, plan.json, built/reopened native records (reactor solver readback, initial mass/volume, per-sample mass/volume/net production rates and the ignition-pass step record), captured mechanism bytes/hash, worker source, stage stdout/stderr, CSV, summary and incomplete/failure results remain in each fresh attempt.",
          "verification": "Pure host NASA7/ideal-gas formulas verify all thermodynamic properties, normalised mass/mole fractions and element inventories. Equilibrium checks all accessible species chemical potentials against element potentials; TP holds T/P, HP holds enthalpy/P. A second Cantera process reloads the saved CSV states. No success flag substitutes for numerical checks. Reactor histories: host Python re-evaluates all 29 h2o2 rates (elementary, three-body, Troe falloff, reverse rates from NASA7 equilibrium constants) and integrates the adiabatic reactor with its own L-stable Rosenbrock method. Native and fresh-process net production rates must agree within 1e-10 of the gross rate; sampled T/X must lie within the independent solution over a 1% time window (plus 0.5 K and 1e-6); the declared ignition delay must agree within 1%; elements, mass, density (constant volume) and specific enthalpy or internal energy are conserved; solver settings and the 1 m3 initial volume are read back. Optional thermal exchange: host independent ODE integrates heat input per fixed initial mass; observed enthalpy/internal-energy change must match it within 1e-6 cp*T0 plus the NASA7 boundary jump. Native Wall coefficient/area, fixed bath, no radiation/expansion and each outward heat rate are read back. Argon heating/cooling have independent analytic expectations in both models."
        },
        "data": [
          {
            "id": "states",
            "direction": "output",
            "kind": "table",
            "format": "numeric CSV",
            "traits": {
              "units": "SI in column names; mole/mass fractions dimensionless",
              "columns": 30,
              "phase": "ideal-gas ohmech"
            },
            "losses": [
              "CSV alone omits input basis, mechanism provenance, reactor model and ignition criterion; retain summary.",
              "No transport, phase transitions, carbon or NOx chemistry; reactor kinetics only for one closed optionally bath-coupled homogeneous reactor."
            ],
            "scope": "One row per independent initial temperature (sweeps) or per requested sample time (reactor histories), ten species X and Y; at most 100 rows."
          },
          {
            "id": "summary",
            "direction": "output",
            "kind": "text",
            "format": "JSON",
            "traits": {
              "mechanism": "h2o2.yaml",
              "phase": "ohmech"
            },
            "losses": [
              "Independent residuals qualify this ideal-gas mechanism, not its suitability for an experiment."
            ],
            "scope": "Input basis, normalised initial composition, mechanism identity, per-row conservation/equilibrium residuals and limits; for reactors also model, solver readback, ignition criterion/delay, independent delay and tolerances."
          }
        ],
        "inspection": [
          {
            "panel": "table",
            "scope": "Inspect times or temperatures, pressure, density, energies, heat capacities and mole/mass fractions in results.csv.",
            "limits": "2\u2013100 finite numeric rows; no native chemistry viewer."
          },
          {
            "panel": "text",
            "scope": "Read chemistry-summary.json for mechanism identity, units, reactor model and ignition criterion, independent checks and loss limits.",
            "limits": "A bounded summary, not interactive native state inspection."
          }
        ],
