          },
          "time-batches": {
            "status": "unsupported",
            "scope": "This bounded batch route does not implement time-batches."
          },
          "source-authoring": {
            "status": "supported",
            "scope": "Shared durable draft JSON editing with revision checks and undo."
          },
          "property-authoring": {
            "status": "supported",
